$all=@(Get-CimInstance Win32_Process); $roots=@($all | Where-Object { $_.CommandLine -like '*dependencies*sync*--all*' -and $_.Name -notlike '*powershell*' }); foreach($r in $roots){$ids=@([int]$r.ProcessId);for($depth=0;$depth -lt 6 -and $ids.Count;$depth++){ $next=@();foreach($id in $ids){$p=$all|Where-Object ProcessId -eq $id; if($p){[PSCustomObject]@{depth=$depth;pid=$p.ProcessId;parent=$p.ParentProcessId;birth=$p.CreationDate.ToUniversalTime().ToString('o');image=$p.ExecutablePath;argv=$p.CommandLine}|ConvertTo-Json -Compress;$next+=@($all|Where-Object ParentProcessId -eq $id|ForEach-Object{[int]$_.ProcessId})}};$ids=$next}}